=== reservations/PriceCalculator.java
     1	package hotel.reservations;
     2	
     3	import hotel.rooms.Room;
     4	import java.math.BigDecimal;
     5	import java.math.RoundingMode;
     6	import java.time.LocalDate;
     7	import java.time.Month;
     8	import java.util.Map;
     9	
    10	/**
    11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
    12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
    13	 * (half-even) at every step.
    14	 */
    15	public final class PriceCalculator {
    16	
    17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
    18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    19	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
    20	    static final Map<String, BigDecimal> COMPANY_DISCOUNTS = Map.of(
    21	            "TECNOSUL", new BigDecimal("0.12"),
    22	            "AGROVALE", new BigDecimal("0.18"),
    23	            "FARMAVIDA", new BigDecimal("0.25"));
    24	
    25	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
    26	        int nights = 0;
    27	        BigDecimal subtotal = cents(BigDecimal.ZERO);
    28	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    29	            subtotal = subtotal.add(nightPrice(room, night));
    30	            nights++;
    31	        }
    32	        if (ratePlan == RatePlan.WEEKEND_PACKAGE) {
    33	            BigDecimal packagePrice = switch (room.type()) {
    34	                case STANDARD -> new BigDecimal("520.00");
    35	                case DELUXE -> new BigDecimal("820.00");
    36	                case SUITE -> new BigDecimal("1200.00");
    37	            };
    38	            return new Price(nights, packagePrice, cents(BigDecimal.ZERO), packagePrice);
    39	        }
    40	        BigDecimal discount = switch (ratePlan) {
    41	            case STANDARD -> cents(BigDecimal.ZERO);
    42	            case NON_REFUNDABLE -> cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
    43	            case CORPORATE -> cents(subtotal.multiply(COMPANY_DISCOUNTS.get(companyCode)));
    44	            case LONG_STAY -> cents(subtotal.multiply(LONG_STAY_DISCOUNT));
    45	            case WEEKEND_PACKAGE -> cents(BigDecimal.ZERO);
    46	        };
    47	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    48	    }
    49	
    50	    BigDecimal nightPrice(Room room, LocalDate night) {
    51	        BigDecimal nightlyRate = room.nightlyRate();
    52	        if (isHighSeason(night)) {
    53	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
    54	        }
    55	        return cents(nightlyRate);
    56	    }
    57	
    58	    /** High season: from December 15 to the end of February, and the whole of July. */
    59	    static boolean isHighSeason(LocalDate date) {
    60	        Month month = date.getMonth();
    61	        return month == Month.JANUARY
    62	                || month == Month.FEBRUARY
    63	                || month == Month.JULY
    64	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
    65	    }
    66	
    67	    static BigDecimal cents(BigDecimal value) {
    68	        return value.setScale(2, RoundingMode.HALF_EVEN);
    69	    }
    70	}
