=== reservations/ReservationService.java
     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	import java.time.DayOfWeek;
     9	import java.time.temporal.ChronoUnit;
    10	
    11	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    12	public final class ReservationService {
    13	
    14	    static final String HOTEL_NAME = "Pousada Maré Alta";
    15	
    16	    private final Rooms rooms;
    17	    private final ReservationStore store;
    18	    private final PriceCalculator priceCalculator;
    19	    private final EmailSender emailSender;
    20	
    21	    public ReservationService(
    22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    23	        this.rooms = rooms;
    24	        this.store = store;
    25	        this.priceCalculator = priceCalculator;
    26	        this.emailSender = emailSender;
    27	    }
    28	
    29	    public synchronized Reservation create(NewReservation request) {
    30	        if (!request.checkOut().isAfter(request.checkIn())) {
    31	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    32	        }
    33	        if (request.guests() < 1) {
    34	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    35	        }
    36	        Room room = rooms.find(request.roomNumber())
    37	                .orElseThrow(() -> new HotelException(
    38	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    39	        if (request.guests() > room.capacity()) {
    40	            throw new HotelException(
    41	                    ErrorCode.CAPACITY_EXCEEDED,
    42	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    43	        }
    44	        boolean roomTaken = store.all().stream()
    45	                .filter(existing -> existing.status() != ReservationStatus.CANCELLED)
    46	                .anyMatch(existing -> existing.overlaps(room.number(), request.checkIn(), request.checkOut()));
    47	        if (roomTaken) {
    48	            throw new HotelException(
    49	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    50	        }
    51	        if (request.ratePlan() == RatePlan.CORPORATE
    52	                && (request.companyCode() == null
    53	                    || !PriceCalculator.COMPANY_DISCOUNTS.containsKey(request.companyCode()))) {
    54	            throw new HotelException(ErrorCode.INVALID_REQUEST,
    55	                    "the CORPORATE plan needs the code of a company with an agreement");
    56	        }
    57	        if (request.ratePlan() == RatePlan.WEEKEND_PACKAGE
    58	                && (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY
    59	                    || !request.checkOut().equals(request.checkIn().plusDays(2)))) {
    60	            throw new HotelException(ErrorCode.INVALID_REQUEST,
    61	                    "the weekend package goes from a Friday to the Sunday right after");
    62	        }
    63	        if (request.ratePlan() == RatePlan.LONG_STAY
    64	                && ChronoUnit.DAYS.between(request.checkIn(), request.checkOut()) < 7) {
    65	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the long stay needs at least 7 nights");
    66	        }
    67	        Price price = priceCalculator.calculate(
    68	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
    69	        Reservation reservation = new Reservation(store.nextId(), request, price);
    70	        store.save(reservation);
    71	        return reservation;
    72	    }
    73	
    74	    public Reservation find(long reservationId) {
    75	        return store.find(reservationId)
    76	                .orElseThrow(() -> new HotelException(
    77	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    78	    }
    79	
    80	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    81	    public synchronized Reservation confirm(long reservationId) {
    82	        Reservation reservation = find(reservationId);
    83	        if (reservation.status() != ReservationStatus.PENDING) {
    84	            throw notAllowed(reservation, "confirm");
    85	        }
    86	        reservation.confirmPayment();
    87	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    88	        emailSender.send(
    89	                reservation.guest().email(),
    90	                "Reserva confirmada - " + HOTEL_NAME,
    91	                confirmationEmailBody(reservation, receipt));
    92	        return reservation;
    93	    }
    94	
    95	    /**
    96	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    97	     * reservation was never paid, so nothing comes back).
    98	     */
    99	    public synchronized Reservation cancel(long reservationId) {
   100	        Reservation reservation = find(reservationId);
   101	        if (reservation.status() != ReservationStatus.PENDING
   102	                && reservation.status() != ReservationStatus.CONFIRMED) {
   103	            throw notAllowed(reservation, "cancel");
   104	        }
   105	        BigDecimal refund = switch (reservation.ratePlan()) {
   106	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
   107	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
   108	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().multiply(new BigDecimal("0.5")));
   109	        };
   110	        reservation.cancel(refund);
   111	        return reservation;
   112	    }
   113	
   114	    public synchronized Reservation checkIn(long reservationId) {
   115	        Reservation reservation = find(reservationId);
   116	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   117	            throw notAllowed(reservation, "check in");
   118	        }
   119	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   120	        return reservation;
   121	    }
   122	
   123	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   124	    public synchronized ReservationReceipt checkOut(long reservationId) {
   125	        Reservation reservation = find(reservationId);
   126	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   127	            throw notAllowed(reservation, "check out");
   128	        }
   129	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   130	        return new ReservationReceipt(reservation, roomOf(reservation));
   131	    }
   132	
   133	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   134	    public ReservationReceipt receiptCopy(long reservationId) {
   135	        Reservation reservation = find(reservationId);
   136	        if (!reservation.isPaid()) {
   137	            throw notAllowed(reservation, "issue a receipt for");
   138	        }
   139	        return new ReservationReceipt(reservation, roomOf(reservation));
   140	    }
   141	
   142	    private Room roomOf(Reservation reservation) {
   143	        return rooms.find(reservation.roomNumber()).orElseThrow();
   144	    }
   145	
   146	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   147	        return "Olá, " + reservation.guest().name() + "!\n\n"
   148	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   149	                + receipt.text() + "\n"
   150	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   151	                + "Até breve!\n";
   152	    }
   153	
   154	    private static HotelException notAllowed(Reservation reservation, String operation) {
   155	        return new HotelException(
   156	                ErrorCode.OPERATION_NOT_ALLOWED,
   157	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   158	    }
   159	}
