=== reservations/ReservationStore.java
     1	package hotel.reservations;
     2	
     3	import java.util.ArrayList;
     4	import java.util.LinkedHashMap;
     5	import java.util.List;
     6	import java.util.Map;
     7	import java.util.Optional;
     8	
     9	/** Keeps the reservations in memory: everything is lost when the service restarts. */
    10	public final class ReservationStore {
    11	
    12	    private final Map<Long, Reservation> reservationsById = new LinkedHashMap<>();
    13	    private long lastId = 0;
    14	
    15	    synchronized long nextId() {
    16	        lastId++;
    17	        return lastId;
    18	    }
    19	
    20	    synchronized void save(Reservation reservation) {
    21	        reservationsById.put(reservation.id(), reservation);
    22	    }
    23	
    24	    public synchronized Optional<Reservation> find(long id) {
    25	        return Optional.ofNullable(reservationsById.get(id));
    26	    }
    27	
    28	    public synchronized List<Reservation> all() {
    29	        return new ArrayList<>(reservationsById.values());
    30	    }
    31	}

