    82	            RevenueReport revenueReport) {
    83	        this.rooms = rooms;
    84	        this.reservations = reservations;
    85	        this.sentMessages = sentMessages;
    86	        this.occupancyReport = occupancyReport;
    87	        this.revenueReport = revenueReport;
    88	
    89	        ObjectMapper jsonMapper = JsonMapper.builder()
    90	                .addModule(new JavaTimeModule())
    91	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    92	                .build();
    93	        this.server = Javalin.create(config -> {
    94	            config.showJavalinBanner = false;
    95	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
    96	        });
    97	        registerRoutes();
    98	        registerErrorHandling();
