   166	                || body.checkOut() == null
   167	                || body.guests() == null
   168	                || body.ratePlan() == null) {
   169	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
   170	        }
   171	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
