   105	    private void registerRoutes() {
   106	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
   107	
   108	        server.post("/reservations", ctx -> {
   109	            NewReservation request = readNewReservation(ctx);
   110	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
   111	        });
   112	        server.get("/reservations/{id}", ctx ->
   113	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
   114	        server.post("/reservations/{id}/confirmation", ctx ->
   115	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
   116	        server.post("/reservations/{id}/cancellation", ctx ->
   117	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
   118	        server.post("/reservations/{id}/check-in", ctx ->
   119	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
   120	        server.post("/reservations/{id}/check-out", ctx ->
   121	                ctx.json(reservations.checkOut(reservationId(ctx))));
   122	        server.get("/reservations/{id}/document", ctx ->
   123	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
   124	
   125	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
   126	
   127	        server.get("/reports/occupancy", ctx -> {
   128	            LocalDate night = readDate(ctx);
   129	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
   130	        });
   131	        server.get("/reports/revenue", ctx -> {
   132	            YearMonth month = readMonth(ctx);
   133	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
   134	        });
   135	    }
