   137	    private void registerErrorHandling() {
   138	        server.exception(HotelException.class, (exception, ctx) -> {
   139	            ctx.status(httpStatus(exception.errorCode()));
   140	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
   141	        });
