   144	    private static int httpStatus(ErrorCode errorCode) {
   145	        return switch (errorCode) {
   146	            case INVALID_REQUEST -> 400;
   147	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
   148	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
   149	            case CAPACITY_EXCEEDED -> 422;
