   186	        String date = requiredQueryParam(ctx, "date");
   187	        try {
   188	            return LocalDate.parse(date);
   189	        } catch (DateTimeParseException badDate) {
   190	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
   191	        }
   192	    }
