   194	    private static YearMonth readMonth(Context ctx) {
   195	        String month = requiredQueryParam(ctx, "month");
   196	        try {
   197	            return YearMonth.parse(month);
   198	        } catch (DateTimeParseException badMonth) {
   199	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
   200	        }
   201	    }
