   203	    private static String requiredQueryParam(Context ctx, String name) {
   204	        String value = ctx.queryParam(name);
   205	        if (value == null) {
   206	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
   207	        }
   208	        return value;
   209	    }
