  9	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
 10	public record ReservationReceipt(
 11	        String title,
 12	        long reservationId,
 13	        String guestName,
 14	        String guestCpf,
 15	        int roomNumber,
 16	        RoomType roomType,
 17	        LocalDate checkIn,
 18	        LocalDate checkOut,
 19	        int nights,
 20	        BigDecimal subtotal,
 21	        BigDecimal discount,
 22	        BigDecimal total) {
 23	
 24	    public ReservationReceipt(Reservation reservation, Room room) {
 25	        this(
 26	                "Comprovante de reserva",
 27	                reservation.id(),
 28	                reservation.guest().name(),
 29	                reservation.guest().cpf(),
 30	                room.number(),
 31	                room.type(),
 32	                reservation.checkIn(),
 33	                reservation.checkOut(),
 34	                reservation.price().nights(),
 35	                reservation.price().subtotal(),
 36	                reservation.price().discount(),
 37	                reservation.price().total());
 38	    }
 39	
 40	    public String text() {
 41	        StringBuilder text = new StringBuilder();
 42	        text.append(title).append(" nº ").append(reservationId).append('\n');
 43	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
 44	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
 45	        text.append("Entrada: ").append(TextFormat.date(checkIn))
 46	                .append(" | Saída: ").append(TextFormat.date(checkOut))
 47	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
 48	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
 49	        if (discount.signum() > 0) {
 50	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
 51	        }
 52	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
 53	        return text.toString();
 54	    }
 55	}
 56	package hotel.reports;
 57	
 58	import hotel.reservations.Reservation;
 59	import hotel.reservations.ReservationStore;
 60	import java.math.BigDecimal;
 61	import java.time.YearMonth;
 62	import java.util.ArrayList;
 63	import java.util.Comparator;
 64	import java.util.List;
 65	
 66	/**
 67	 * The money the inn kept from the reservations that start in a given month, for the accountant (CSV).
 68	 * A cancelled non-refundable reservation counts: the guest paid and nothing went back.
 69	 */
 70	public final class RevenueReport {
 71	
 72	    private final ReservationStore store;
 73	
 74	    public RevenueReport(ReservationStore store) {
 75	        this.store = store;
 76	    }
 77	
 78	    public String generate(YearMonth month) {
 79	        List<Reservation> withRevenue = new ArrayList<>();
 80	        for (Reservation reservation : store.all()) {
 81	            boolean keptMoney = reservation.amountKept().signum() > 0;
 82	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
 83	            if (keptMoney && startsInMonth) {
 84	                withRevenue.add(reservation);
 85	            }
 86	        }
 87	        withRevenue.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
 88	
 89	        StringBuilder csv = new StringBuilder();
 90	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 91	        BigDecimal revenue = BigDecimal.ZERO.setScale(2);
 92	        for (Reservation reservation : withRevenue) {
 93	            csv.append(reservation.id()).append(',')
 94	                    .append(reservation.roomNumber()).append(',')
 95	                    .append(reservation.checkIn()).append(',')
 96	                    .append(reservation.checkOut()).append(',')
 97	                    .append(reservation.status()).append(',')
 98	                    .append(reservation.amountKept().toPlainString()).append('\n');
 99	            revenue = revenue.add(reservation.amountKept());
100	        }
101	        csv.append("total,").append(revenue.toPlainString()).append('\n');
102	        return csv.toString();
103	    }
104	}
